package io.github.polestarcn.companion;
import static org.junit.Assert.*;
import android.app.*;import android.content.*;import android.content.res.Configuration;import android.graphics.*;import android.view.*;import android.widget.*;
import java.io.*;import java.lang.reflect.*;import java.util.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class V085RegressionTest {
 private AppRegressionTest base;private MainActivity a;private VehicleCoordinator model;
 @Before public void start()throws Exception{base=new AppRegressionTest();base.start();Field f=AppRegressionTest.class.getDeclaredField("activity");f.setAccessible(true);a=(MainActivity)f.get(base);model=VehicleCoordinator.get(a);f=VehicleCoordinator.class.getDeclaredField("signedIn");f.setAccessible(true);f.setBoolean(model,true);model.selected=new io.github.polestarcn.companion.api.ChinaPolestarApi.VehicleInfo();model.selected.vin="FIXTURE-V085";model.snapshot=sample();AppPreferences.set(a,"language","zh");}
 @After public void stop(){AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();if(d!=null)d.dismiss();base.stop();}
 private VehicleSnapshot sample(){long now=System.currentTimeMillis();return new VehicleSnapshot("Polestar 2","masked",63,230,65845,"空闲","全部关闭","全部关闭","已关闭","已上锁",now,"LIVE",false,"关闭","关闭").withHealth(new VehicleHealthSnapshot(1,1,-1,now,-1,2,1,-1,-1,931,75,14959));}
 private void invoke(String name)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name);m.setAccessible(true);m.invoke(a);}
 private void page(int value)throws Exception{Field f=MainActivity.class.getDeclaredField("page");f.setAccessible(true);f.setInt(a,value);invoke("render");}
 private View root(){return a.getWindow().getDecorView();}
 private View tag(String name){View v=root().findViewWithTag(name);assertNotNull(name,v);return v;}
 private void open(String key){tag("disclosure_header_"+key).performClick();}
 private void export(String name)throws Exception{View v=root();v.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(780,View.MeasureSpec.EXACTLY));v.layout(0,0,360,780);File f=new File("build/reports/previews/v085/"+name+".png");f.getParentFile().mkdirs();Bitmap bitmap=Bitmap.createBitmap(720,1560,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(bitmap);c.scale(2,2);v.draw(c);try(FileOutputStream out=new FileOutputStream(f)){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
 @Test public void conditionEntryWorksInAllSkinsEvenWhenSnapshotIsMissing()throws Exception{for(String skin:UiSkin.CHOICES)for(boolean missing:new boolean[]{false,true}){UiSkin.set(a,skin);model.snapshot=missing?null:sample();page(0);View button=tag("exterior_button");assertTrue(button.isEnabled());AlertDialog before=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();button.performClick();AlertDialog popup=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotSame(before,popup);assertNotNull(popup.findViewById(android.R.id.content).findViewWithTag("car_condition_popup"));popup.dismiss();tag("exterior_button");}}
 @Test public void reportedWarningsAndTwelveVoltPrecedeMissingChecks()throws Exception{invoke("vehicleStatusDialog");View brake=tag("health_row_制动液"),battery=tag("health_row_12V 电池");ViewGroup parent=(ViewGroup)brake.getParent();assertTrue(parent.indexOfChild(brake)<parent.indexOfChild(battery));assertNull(root().findViewWithTag("health_row_机油（适用时）"));assertEquals(View.GONE,tag("disclosure_content_status_missing").getVisibility());open("status_missing");tag("health_row_机油（适用时）");assertEquals(View.VISIBLE,tag("disclosure_content_status_missing").getVisibility());}
 @Test public void serviceAndDoorSectionsExpandAndCollapseWithoutDialogs()throws Exception{invoke("vehicleStatusDialog");AlertDialog before=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();for(String key:new String[]{"status_service","status_exterior","status_tyres"}){open(key);assertEquals(View.VISIBLE,tag("disclosure_content_"+key).getVisibility());open(key);assertEquals(View.GONE,tag("disclosure_content_"+key).getVisibility());}assertSame(before,org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog());}
 @Test public void settingsAreOrderedAndWidgetPreferenceSurvivesRebuild()throws Exception{page(2);String[] keys={"appearance","home","widget","vehicle","background","watch","account"};ViewGroup parent=(ViewGroup)tag("disclosure_settings_appearance").getParent();int old=-1;for(String key:keys){View frame=tag("disclosure_settings_"+key);int index=parent.indexOfChild(frame);assertTrue(index>old);old=index;}assertFalse(root().findViewWithTag("widget_bold").isShown());open("settings_widget");android.widget.CompoundButton bold=(android.widget.CompoundButton)tag("widget_bold");bold.setChecked(true);assertTrue(AppPreferences.visible(a,"widget_bold",false));invoke("render");assertEquals(View.VISIBLE,tag("disclosure_content_settings_widget").getVisibility());assertTrue(((android.widget.CompoundButton)tag("widget_bold")).isChecked());}
 @Test public void expansionAndReturnPageRemainStableAcrossModelRefresh()throws Exception{page(2);open("settings_home");invoke("maintenanceDialog");tag("status_scroll");assertEquals(View.VISIBLE,tag("disclosure_content_status_service").getVisibility());invoke("onModelChanged");assertEquals(View.VISIBLE,tag("disclosure_content_status_service").getVisibility());a.onBackPressed();assertEquals(View.VISIBLE,tag("disclosure_content_settings_home").getVisibility());}
 @Test public void allVehicleDataDetailsUseInlineSections()throws Exception{page(1);AlertDialog before=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();for(String key:new String[]{"data_exterior","data_tyres","data_trips","data_air","data_service","data_identity"}){open(key);assertEquals(View.VISIBLE,tag("disclosure_content_"+key).getVisibility());}assertSame(before,org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog());}
 @Test public void iTpmsDiagramPreferenceOnlyControlsDiagramNotReportedStates()throws Exception{AppPreferences.set(a,"experimental_tire","off");invoke("tireDialog");assertNull(findType(tag("disclosure_content_status_tyres"),TirePressureView.class));AppPreferences.set(a,"experimental_tire","on");invoke("render");assertNotNull(findType(tag("disclosure_content_status_tyres"),TirePressureView.class));}
 private View findType(View v,Class<?> c){if(c.isInstance(v))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View match=findType(((ViewGroup)v).getChildAt(i),c);if(match!=null)return match;}return null;}
 @Test public void standaloneConfigDoesNotDependOnInstalledAppsOrPriorImport()throws Exception{a.getSharedPreferences("reference_import",0).edit().clear().commit();boolean bundled;try(InputStream in=a.getAssets().open("client-signing.bin")){bundled=true;}catch(IOException noPrivateConfig){bundled=false;}io.github.polestarcn.companion.auth.ClientSignatureProvider signer=new io.github.polestarcn.companion.auth.ClientSignatureProvider(a);assertEquals(bundled,signer.isReady());if(bundled)assertEquals(32,signer.resolve().length());page(0);assertFalse(contains(root(),"导入模板"));}
 private boolean contains(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().contains(text))return true;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)if(contains(((ViewGroup)v).getChildAt(i),text))return true;return false;}
 @Test public void noSelectedVehicleStillAllowsDiscoveryRetryFromConditionPage()throws Exception{model.selected=null;model.snapshot=null;invoke("vehicleStatusDialog");assertTrue(tag("condition_refresh").isEnabled());}
 @Test public void partialTyreReportsRemainAmongReportedChecks()throws Exception{model.snapshot=model.snapshot.withTires(new TireSnapshot(new Double[]{null,null,null,null},new int[]{1,-1,-1,-1},System.currentTimeMillis()));invoke("vehicleStatusDialog");assertTrue(tag("health_row_胎压告警").getContentDescription().toString().contains("部分"));}
 @Test public void widgetStatusRouteOpensTheSameInlinePage()throws Exception{Intent intent=new Intent(a,MainActivity.class).setAction("io.github.polestarcn.companion.WIDGET").putExtra("widget_action","status");Method m=MainActivity.class.getDeclaredMethod("handleWidgetIntent",Intent.class);m.setAccessible(true);m.invoke(a,intent);tag("status_scroll");assertFalse(intent.hasExtra("widget_action"));}
 @Test public void disclosureArrowFitsLargeEnglishSystemFont()throws Exception{Configuration c=new Configuration(a.getResources().getConfiguration());c.fontScale=2f;android.util.DisplayMetrics m=a.getResources().getDisplayMetrics();m.scaledDensity=m.density*2;a.getResources().updateConfiguration(c,m);AppPreferences.set(a,"language","en");page(2);View v=root();v.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(640,View.MeasureSpec.EXACTLY));v.layout(0,0,360,640);LinearLayout header=(LinearLayout)tag("disclosure_header_settings_appearance");TextView arrow=(TextView)header.getChildAt(1);assertNotNull(arrow.getLayout());assertTrue(arrow.getLayout().getHeight()<=arrow.getHeight()-arrow.getCompoundPaddingTop()-arrow.getCompoundPaddingBottom());}
 @Test public void exportsThreeImplementedPages()throws Exception{Configuration c=new Configuration(a.getResources().getConfiguration());c.screenWidthDp=360;c.screenHeightDp=780;c.fontScale=1;android.util.DisplayMetrics metrics=a.getResources().getDisplayMetrics();metrics.scaledDensity=metrics.density;a.getResources().updateConfiguration(c,metrics);page(2);export("settings");invoke("vehicleStatusDialog");export("condition");open("status_service");export("condition-expanded");}
}
